import { index, jsonb, pgTable, real, serial, text, timestamp } from "drizzle-orm/pg-core";

/** Saved construction cost estimates generated by the wizard. */
export const estimates = pgTable("estimates", {
  id: serial("id").primaryKey(),
  refCode: text("ref_code").notNull().unique(),
  createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),

  /** Full input snapshot (CalcInputs). */
  inputsJson: jsonb("inputs_json").notNull().$type<Record<string, unknown>>(),

  // Derived project identity labels
  provinceLabel: text("province_label").notNull(),
  usageLabel: text("usage_label").notNull(),
  structureLabel: text("structure_label").notNull(),
  qualityLabel: text("quality_label").notNull(),

  landArea: real("land_area").notNull(),
  floors: real("floors").notNull(),
  totalUnits: real("total_units").notNull(),
  builtUpArea: real("built_up_area").notNull(),

  // Result snapshot (decimal strings in toman to avoid float issues)
  baseTotal: text("base_total").notNull(),
  feesTotal: text("fees_total").notNull(),
  grandTotal: text("grand_total").notNull(),
  costPerSqm: text("cost_per_sqm").notNull(),

  /** Breakdown groups with line items. */
  groupsJson: jsonb("groups_json").notNull().$type<unknown[]>(),
  /** Extra computed metadata (per-sqm scenario comparison, formulas…). */
  metaJson: jsonb("meta_json").notNull().$type<Record<string, unknown>>(),
}, (table) => [index("estimates_created_at_idx").on(table.createdAt)]);

/** Admin overrides applied on top of the built-in price catalog (percent delta). */
export const priceOverrides = pgTable("price_overrides", {
  id: serial("id").primaryKey(),
  itemKey: text("item_key").notNull().unique(),
  adjustPct: real("adjust_pct").notNull().default(0),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
});

/**
 * Market price indices (modeled on سازمان برنامه «شاخص تعدیل»).
 * kind: 'material' | 'wage' — base value 100 at the reference date (1405/08/28).
 * Between admin updates, an automatic monthly drift keeps them fresh.
 */
export const priceIndices = pgTable("price_indices", {
  id: serial("id").primaryKey(),
  kind: text("kind").notNull().unique(),
  value: real("value").notNull().default(100),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
});

/** Simple key/value app settings (e.g. automatic drift rate). */
export const appSettings = pgTable("app_settings", {
  key: text("key").primaryKey(),
  value: text("value").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
});
